// s5_expr.js - Expression evaluator with + - * / operations

/**
 * Evaluates a mathematical expression containing +, -, *, / operators
 * @param {string} expr - The expression to evaluate
 * @returns {number} - The result of the evaluation
 */
function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error('Empty expression');
    }

    // Check for invalid characters
    if (!/^[0-9+\-*/.()]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }

    // Handle parentheses first
    while (expr.includes('(')) {
        const start = expr.lastIndexOf('(');
        const end = expr.indexOf(')', start);
        if (end === -1) {
            throw new Error('Mismatched parentheses');
        }
        const subExpr = expr.substring(start + 1, end);
        const result = evaluate(subExpr);
        expr = expr.substring(0, start) + result + expr.substring(end + 1);
    }

    // First pass: handle multiplication and division
    let i = 0;
    while (i < expr.length) {
        if (expr[i] === '*') {
            const left = parseNumber(expr, i - 1, true);
            const right = parseNumber(expr, i + 1, false);
            const result = left * right;
            expr = expr.substring(0, i - left.toString().length) + result + expr.substring(i + right.toString().length + 1);
            i = i - left.toString().length + result.toString().length;
        } else if (expr[i] === '/') {
            const left = parseNumber(expr, i - 1, true);
            const right = parseNumber(expr, i + 1, false);
            if (right === 0) {
                throw new Error('Division by zero');
            }
            const result = left / right;
            expr = expr.substring(0, i - left.toString().length) + result + expr.substring(i + right.toString().length + 1);
            i = i - left.toString().length + result.toString().length;
        } else {
            i++;
        }
    }

    // Second pass: handle addition and subtraction
    i = 0;
    while (i < expr.length) {
        if (expr[i] === '+') {
            const left = parseNumber(expr, i - 1, true);
            const right = parseNumber(expr, i + 1, false);
            const result = left + right;
            expr = expr.substring(0, i - left.toString().length) + result + expr.substring(i + right.toString().length + 1);
            i = i - left.toString().length + result.toString().length;
        } else if (expr[i] === '-') {
            // Handle negative numbers
            if (i === 0 || expr[i-1] === '+' || expr[i-1] === '-' || expr[i-1] === '*' || expr[i-1] === '/') {
                // This is a negative number, not subtraction
                i++;
            } else {
                const left = parseNumber(expr, i - 1, true);
                const right = parseNumber(expr, i + 1, false);
                const result = left - right;
                expr = expr.substring(0, i - left.toString().length) + result + expr.substring(i + right.toString().length + 1);
                i = i - left.toString().length + result.toString().length;
            }
        } else {
            i++;
        }
    }

    // If we have a single number, return it
    if (expr.length > 0 && !isNaN(expr) && expr !== '') {
        return parseFloat(expr);
    }

    throw new Error('Invalid expression');
}

/**
 * Parses a number from the expression string
 * @param {string} expr - The expression
 * @param {number} pos - Position to start parsing
 * @param {boolean} left - True if parsing left side of operator, false if right
 * @returns {number} - The parsed number
 */
function parseNumber(expr, pos, left) {
    let start = pos;
    let end = pos;

    // Parse the number from the given position
    if (left) {
        // Parse left side (towards the beginning)
        while (start >= 0 && (/[0-9.]/.test(expr[start]))) {
            start--;
        }
        start++;
        // Skip any leading minus sign for negative numbers
        if (start > 0 && expr[start-1] === '-') {
            start--;
        }
    } else {
        // Parse right side (towards the end)
        while (end < expr.length && (/[0-9.]/.test(expr[end]))) {
            end++;
        }
    }

    const numStr = expr.substring(start, end);
    return parseFloat(numStr);
}

