def has_cycle(self):
    """Detect if the graph has a directed cycle.

    Returns:
        bool: True if the graph contains a directed cycle, False otherwise.
        An edge from a node to itself counts as a cycle.
    """
    # Keep track of visited nodes and recursion stack
    visited = set()
    rec_stack = set()

    def dfs(node):
        # Mark current node as visited and add to recursion stack
        visited.add(node)
        rec_stack.add(node)

        # Check all neighbors
        for neighbor, _ in self.neighbors(node):
            # If neighbor is not visited, recursively check it
            if neighbor not in visited:
                if dfs(neighbor):
                    return True
            # If neighbor is in recursion stack, we found a cycle
            elif neighbor in rec_stack:
                return True

        # Remove node from recursion stack
        rec_stack.remove(node)
        return False

    # Check for cycles starting from each node
    for node in self.nodes():
        if node not in visited:
            if dfs(node):
                return True

    return False

get(key) {
  if (!this.map.has(key)) {
    return undefined;
  }

  // Get the value and move to end (most recently used)
  const value = this.map.get(key);
  this.map.delete(key);
  this.map.set(key, value);

  return value;
}

peek(key) {
  return this.map.get(key);
}

