    student_assignments = self.students[student]
    if not student_assignments:
        return None

    # Group assignments by category
    category_scores = {}
    category_max_points = {}

    for assignment, score in student_assignments.items():
        assignment_info = self.assignments[assignment]
        if score is not None:
            category = assignment_info["category"]
            max_points = assignment_info["max_points"]

            if category not in category_scores:
                category_scores[category] = 0
                category_max_points[category] = 0

            category_scores[category] += score
            category_max_points[category] += max_points

    # If no assignments, return None
    if not category_scores:
        return None

    # If only one category, calculate simple average (as per requirement)
    if len(category_scores) == 1:
        category = list(category_scores.keys())[0]
        score = category_scores[category]
        max_points = category_max_points[category]
        return round((score / max_points) * 100, 2)

    # Calculate weighted average
    total_weighted_percentage = 0
    total_weight = 0

    for category, score in category_scores.items():
        max_points = category_max_points[category]
        # If no weight is set, default to 1
        weight = self.categories.get(category, 1)
        percentage = (score / max_points) * 100
        total_weighted_percentage += percentage * weight
        total_weight += weight

    return round(total_weighted_percentage / total_weight, 2)

