class Cache {
  constructor(capacity, options = {}) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new Error('Capacity must be a positive integer');
    }

    this.capacity = capacity;
    this.map = new Map();
    this.ttl = options.ttl || null;
    this.now = options.now || (() => Date.now());
  }

set(key, value, options = {}) {
  // If key exists, update it and move to end (most recently used)
  if (this.map.has(key)) {
    this.map.delete(key);
  }

  // Add new key-value pair with timestamp
  const entry = {
    value: value,
    timestamp: this.now()
  };

  // Apply TTL from options or default TTL
  if (options.ttl !== undefined) {
    entry.ttl = options.ttl;
  } else if (this.ttl !== null) {
    entry.ttl = this.ttl;
  }

  this.map.set(key, entry);

  // If cache is over capacity, remove the least recently used item
  if (this.map.size > this.capacity) {
    const firstKey = this.map.keys().next().value;
    this.map.delete(firstKey);
  }
}

get(key) {
  if (!this.map.has(key)) {
    return undefined;
  }

  const entry = this.map.get(key);

  // Check if entry has expired
  if (entry.ttl !== undefined) {
    const age = this.now() - entry.timestamp;
    if (age > entry.ttl) {
      this.map.delete(key);
      return undefined;
    }
  } else if (this.ttl !== null) {
    const age = this.now() - entry.timestamp;
    if (age > this.ttl) {
      this.map.delete(key);
      return undefined;
    }
  }

  // Get the value and move to end (most recently used)
  const value = entry.value;
  this.map.delete(key);
  this.map.set(key, entry);

  return value;
}

peek(key) {
  if (!this.map.has(key)) {
    return undefined;
  }

  const entry = this.map.get(key);

  // Check if entry has expired
  if (entry.ttl !== undefined) {
    const age = this.now() - entry.timestamp;
    if (age > entry.ttl) {
      this.map.delete(key);
      return undefined;
    }
  } else if (this.ttl !== null) {
    const age = this.now() - entry.timestamp;
    if (age > this.ttl) {
      this.map.delete(key);
      return undefined;
    }
  }

  return entry.value;
}

has(key) {
  if (!this.map.has(key)) {
    return false;
  }

  const entry = this.map.get(key);

  // Check if entry has expired
  if (entry.ttl !== undefined) {
    const age = this.now() - entry.timestamp;
    if (age > entry.ttl) {
      this.map.delete(key);
      return false;
    }
  } else if (this.ttl !== null) {
    const age = this.now() - entry.timestamp;
    if (age > this.ttl) {
      this.map.delete(key);
      return false;
    }
  }

  return true;
}

size() {
  let count = 0;
  for (const [key, entry] of this.map.entries()) {
    // Check if entry has expired
    if (entry.ttl !== undefined) {
      const age = this.now() - entry.timestamp;
      if (age <= entry.ttl) {
        count++;
      }
    } else if (this.ttl !== null) {
      const age = this.now() - entry.timestamp;
      if (age <= this.ttl) {
        count++;
      }
    } else {
      count++;
    }
  }
