  determinant() {
    const shape = this.shape();
    const rows = shape[0];
    const cols = shape[1];

    // Check if matrix is square
    if (rows !== cols) {
      throw new Error("Determinant can only be calculated for square matrices");
    }

    // Base case: 1x1 matrix
    if (rows === 1) {
      return this.get(0, 0);
    }

    // Base case: 2x2 matrix
    if (rows === 2) {
      return this.get(0, 0) * this.get(1, 1) - this.get(0, 1) * this.get(1, 0);
    }

    // For larger matrices, use cofactor expansion along the first row
    let det = 0;
    for (let j = 0; j < cols; j++) {
      // Create minor matrix by removing row 0 and column j
      const minorRows = [];
      for (let i = 1; i < rows; i++) {
        const minorRow = [];
        for (let k = 0; k < cols; k++) {
          if (k !== j) {
            minorRow.push(this.get(i, k));
          }
        }
        minorRows.push(minorRow);
      }

      // Calculate cofactor
      const sign = Math.pow(-1, j);
      const cofactor = sign * new Matrix(minorRows).determinant();
      det += this.get(0, j) * cofactor;
    }

